// Which image a shared link shows. Plain functions without imports (tests/share-images.test.mjs).

export type ShareImage = { url: string; width?: number; height?: number; alt?: string; type?: string };

// public/og-default.png, generated by scripts/generate-share-assets.mjs.
export const DEFAULT_SHARE_IMAGE: ShareImage = { url: "/og-default.png", width: 1200, height: 630, alt: "estatemarket24", type: "image/png" };

export function absoluteShareUrl(url: string, base: string) {
  return /^https?:\/\//i.test(url) ? url : base.replace(/\/$/, "") + (url.startsWith("/") ? url : "/" + url);
}

// Listing previews: the first photo comes first, because it is what people want to see and it is a
// small JPEG/WebP file. The branded card (app/ilan/[id]/share-image: title, price, place, purpose and
// logo) follows as a second image, and is the only one for a listing without photos. The card does not
// contain the photo: next/og cannot read WebP, the format of uploaded photos (lib/photo-optimize.ts), and
// a PNG card with a photo is about 0.9 MB, above what WhatsApp shows as a preview.
function version(value: string) {
  let hash = 0;
  for (const char of value) hash = (hash * 31 + char.charCodeAt(0)) | 0;
  return (hash >>> 0).toString(36);
}

export function listingShareCard(listing: { id: string; title: string; price: number; currency?: string; purpose?: string; updatedAt?: string }, locale: string): ShareImage {
  const query = new URLSearchParams({ v: version(`${listing.updatedAt || ""}|${listing.price}|${listing.currency || ""}|${listing.purpose || ""}|${listing.title}`) });
  if (locale !== "tr") query.set("lang", locale);
  return { url: `/ilan/${encodeURIComponent(listing.id)}/share-image?${query}`, width: 1200, height: 630, alt: listing.title, type: "image/png" };
}

export function listingShareImages(listing: { id: string; title: string; images: string[]; price: number; currency?: string; purpose?: string; updatedAt?: string }, locale: string): ShareImage[] {
  const photo = listing.images.find((url) => typeof url === "string" && url.length > 0);
  const card = listingShareCard(listing, locale);
  const type = /.webp$/i.test(photo?.split("?")[0] || "") ? "image/webp" : /.png$/i.test(photo?.split("?")[0] || "") ? "image/png" : /.jpe?g$/i.test(photo?.split("?")[0] || "") ? "image/jpeg" : undefined;
  return photo ? [{ url: photo, alt: listing.title, ...(type ? { type } : {}) }, card] : [card];
}

export function coverShareImage(photo: string | null | undefined, alt: string): ShareImage {
  return photo ? { url: photo, alt } : DEFAULT_SHARE_IMAGE;
}

// Price for the card. Turkish lira as "TL": the embedded font has no ₺ glyph.
export function sharePrice(price: number, currency: string, locale: string) {
  const symbol = ({ TRY: "TL", EUR: "€", USD: "$", GBP: "£" } as Record<string, string>)[currency] || currency;
  const number = new Intl.NumberFormat(locale === "en" ? "en-GB" : locale === "tr" ? "tr-TR" : locale, { maximumFractionDigits: 0 }).format(price);
  return locale === "en" && currency !== "TRY" ? symbol + number : `${number} ${symbol}`;
}
